                                var A = [t1.hp, t1.maxHp, t1.maxHp - t1.hp, t1.countCards('h')];
                                var B = [t2.hp, t2.maxHp, t2.maxHp - t2.hp, t2.countCards('h')];
                                var n1 = [];
                                for (var n of A) {
                                    if (B.includes(n)) {
                                        n1.push(n);
                                    }
                                }
                                var eff = Math.max.apply(null, n1) - Math.min.apply(null, n1);
                                return att > 0 ? eff : -eff;
