                    event.tar = trigger.targets[0];
                    event.tar.chooseCard(str, 'he', num).set('ai', function (card) {
                        var cs = player.getCards('he');
                        var eff = cs.length;
                        if (player.countCards('h') <= 0) {
                            eff = -1;
                        }
                        if (player.hp <= 1) {
                            eff = 2 * eff;
                        }
                        var att = get.attitude(event.tar, player);
                        if (att > 0) {
                            return eff;
                        } else {
                            if (player.storage.xx_chini && player.hp <= 1 && !player.storage.xx_popan_pan) {
                                return -eff;
                            } else {
                                if (player.storage.xx_popan_pan) {
                                    return 4 - get.value(card);
                                }
                                return 8 - get.value(card);
                            }
                        }
                    });
