            xx_weimeng: {
                audio: 'jimeng',
                trigger: {
                    player: 'phaseDrawBegin1',
                },
                forced: true,
                content() {
                    'step 0';
                    player
                        .chooseTarget('危盟:你可以改为获得一名其他角色x张牌,你展示所有手牌并交给其y张手牌(x为其体力值,y为你体力值).', function (c, p, t) {
                            return t != p && t.countCards('he');
                        })
                        .set('ai', function (tar) {
                            var att = get.attitude(player, tar);
                            var cn1 = tar.countCards('h');
                            var cn2 = player.countCards('h');
                            var n1 = Math.min(tar.hp, tar.countCards('he'));
                            var n2 = player.hp;
                            var eff = n1 - n2;
                            if (eff > 0) {
                                if (att < 0) eff += 2;
                            }
                            if (cn2 + n1 - n2 < cn1 - n1 + n2) {
                                eff += 2;
                            }
                            if (cn2 + n1 - n2 > cn1 - n1 + n2) {
                                if (att <= 0) eff -= 3;
                                else eff += 2;
                            }
                            return eff;
                        });
                    ('step 1');
                    if (result.bool) {
                        trigger.cancel();
                        var tar = result.targets[0];
                        event.tar = tar;
                        var n = tar.hp;
                        player.gainPlayerCard(tar, 'he', n, true).set('ai', function (button) {
                            return get.value(button.link);
                        });
                    } else {
                        event.finish();
                    }
                    ('step 2');
                    player.showHandcards(get.translation(player) + '发动了【危盟】');
                    var n = player.hp;
                    player
                        .chooseCard('h', n, true)
                        .set('ai', function (card) {
                            var att = get.attitude(player, event.tar);
                            if (att <= 0) return 4 - get.value(card);
                            return 6 - get.value(card);
                        })
                        .set('prompt2', '危盟:交给' + get.translation(event.tar) + '' + n + '张手牌.');
                    ('step 3');
                    player.give(result.cards, event.tar);
                    ('step 4');
                    var t;
                    if (player.countCards('h') < event.tar.countCards('h')) {
                        t = player;
                    }
                    if (event.tar.countCards('h') < player.countCards('h')) {
                        t = event.tar;
                    }
                    if (t) {
                        t.draw(2);
                    }
                },
            },
