    //霹雳火、盖亚等机甲角色自带护甲
    lib.skill._xx_jijia = {
        forced: true,
        charlotte: true,
        _priority: 999,
        trigger: {
            player: 'phaseZhunbeiBegin',
        },
        filter(event, player) {
            if (!lib.character[player.name]) return false;
            var arr = lib.character[player.name][4];
            if (arr.includes('xx_jijia_s')) return player.hujia < 1;
            return false;
        },
        content() {
            player.changeHujia(1);
        },
    };
    //添加属性
    lib.skill._xx_shuxing_x = {
        forced: true,
        charlotte: true,
        _priority: 999,
        trigger: {
            global: 'phaseBefore',
            player: 'enterGame',
        },
        shuxings: [
            // 水
            'xx_shuxing_shui',
            // 火
            'xx_shuxing_huo',
            // 草
            'xx_shuxing_cao',
            // 土
            'xx_shuxing_tu',
            // 冰
            'xx_shuxing_bing',
            // 风
            'xx_shuxing_feng',
            // 幽灵
            'xx_shuxing_youling',
            // 恶魔
            'xx_shuxing_emo',
            // 毒
            'xx_shuxing_du',
            // 石
            'xx_shuxing_shi',
            // 光
            'xx_shuxing_guang',
            // 机械
            'xx_shuxing_jixie',
            // 电
            'xx_shuxing_dian',
            // 龙
            'xx_shuxing_long',
        ],
        filter(event, player) {
            if (!player.name || !lib.character[player.name] || !lib.character[player.name][4]) return false;
            var arr = lib.character[player.name][4];
            var list = [];
            var nlist = lib.skill._xx_shuxing_x.shuxings;
            for (var name of arr) {
                if (nlist.includes(name)) {
                    list.push(name);
                }
            }
            return list && list.length && list.length;
        },
        content() {
            'step 0';
            var arr = lib.character[player.name][4];
            var list = [];
            var nlist = lib.skill._xx_shuxing_x.shuxings;
            for (var name of arr) {
                if (nlist.includes(name)) {
                    list.push(name);
                }
            }
            player.storage.xx_shuxing = list;
            ('step 1');
            if (player.storage.xx_shuxing) {
                for (var name of player.storage.xx_shuxing) {
                    if (lib.skill[name]) player.addSkill(name);
                }
            }
        },
    };
    // 环境消耗持续回合
    lib.skill._xx_huanjing_end = {
        forced: true,
        charlotte: true,
        _priority: 999,
        trigger: {
            player: 'phaseAfter',
        },
        filter(event, player) {
            return player.xx_game_get_huanjing();
        },
        content() {
            'step 0';
            player.xx_remove_huanjing(1);
            ('step 1');
            event.finish();
            ('step 2');
            var hj = player.xx_game_get_huanjing();
            var tar = hj[0];
            tar.removeMark(hj[1], 1);
            event.tar = tar;
            event.hj = hj;
            ('step 3');
            if (event.tar.countMark(event.hj[1]) < 1) {
                event.tar.removeSkill(event.hj[1]);
                game.broadcastAll(function () {
                    delete _status.xx_hj_tempBackground;
                    game.xx_updateBackground();
                });
            }
        },
    };
